 "content": "def transform(grid):
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    # A horizontal bar's missing continuation is painted 1. In examples, the
    # bar is recognizable by same-color cells at the row edge and a gap interval.
    for r, row in enumerate(grid):
        # Detect color runs and only fill a gap after a run touching an edge,
        # when this row contains a single color and remaining cells are bg.
        colors = {v for v in row if v != bg}
        if len(colors) != 1:
            continue
        color = next(iter(colors))
        cols = [c for c,v in enumerate(row) if v == color]
        lo, hi = min(cols), max(cols)
        # The cases demonstrated: left prefix followed by bg gap -> fill gap;
        # or right-end short trailing gap after the bar component.
        if cols == list(range(lo, hi+1)):
            # Only select when there's a clearly bounded/remaining suffix and
            # the segment starts at the left edge (or ends at the right edge).
            if lo == 0 and hi < len(row)-1:
                for c in range(hi+1, len(row)):
                    out[r][c] = 1
            elif hi == len(row)-1 and lo > 0:
                for c in range(lo):
                    out[r][c] = 1
    return out

if __name__ == '__main__':
    pass
